export interface object_t {
  words: readonly string[];
  inventory: string | null;
  plac: number;
  fixd: number;
  is_treasure: boolean;
  descriptions: readonly (string | null)[];
  sounds: readonly (string | null)[];
  texts: readonly (string | null)[];
  changes: readonly (string | null)[];
}
export interface location_t { description: { small: string | null; big: string | null }; sound: number; loud: boolean }
export interface hint_t { number: number; turns: number; penalty: number; question: string; hint: string }
export interface action_t { words: readonly string[]; message: string | null; noaction: boolean }
export interface travelop_t { motion: number; condtype: number; condarg1: number; condarg2: number; desttype: number; destval: number; nodwarves: boolean; stop: boolean }

